-- {FINAL} for 11_: one row per (dict, group) cell (totals summed in 10_build_tables.py; GROUPING SETS timed out). No cross join (the cross-join version timed out).
-- Output: d|grp|n|cl| then for each rule r0..r11 a block 'F,Fh,Fv,Fc,Fn,Fcl,NEW,LOST,Fclh' separated by '|'.
-- NEW = fires today's counterpart did not fire; LOST = today's counterpart fires this rule does not fire. Counterpart: today ST (r0) for
-- rules 0 and 3-7, today LT (r1) for 1 and 8-9, today ST or LT (r2) for 2 and 10-11.
SELECT COALESCE(d::STRING,'ALL')||'|'||COALESCE(grp,'ALL')||'|'||COUNT(*)||'|'||SUM(cl)||'|'||SUM(r0)||','||SUM(r0*hi)||','||SUM(r0*ver)||','||SUM(r0*chl)||','||SUM(r0*chns)||','||SUM(r0*cl)||','||SUM(r0*(1-r0))||','||SUM(r0*(1-r0))||','||SUM(r0*cl*hi)||'|'||SUM(r1)||','||SUM(r1*hi)||','||SUM(r1*ver)||','||SUM(r1*chl)||','||SUM(r1*chns)||','||SUM(r1*cl)||','||SUM(r1*(1-r0))||','||SUM(r0*(1-r1))||','||SUM(r1*cl*hi)||'|'||SUM(r2)||','||SUM(r2*hi)||','||SUM(r2*ver)||','||SUM(r2*chl)||','||SUM(r2*chns)||','||SUM(r2*cl)||','||SUM(r2*(1-r0))||','||SUM(r0*(1-r2))||','||SUM(r2*cl*hi)||'|'||SUM(r3)||','||SUM(r3*hi)||','||SUM(r3*ver)||','||SUM(r3*chl)||','||SUM(r3*chns)||','||SUM(r3*cl)||','||SUM(r3*(1-r0))||','||SUM(r0*(1-r3))||','||SUM(r3*cl*hi)||'|'||SUM(r4)||','||SUM(r4*hi)||','||SUM(r4*ver)||','||SUM(r4*chl)||','||SUM(r4*chns)||','||SUM(r4*cl)||','||SUM(r4*(1-r0))||','||SUM(r0*(1-r4))||','||SUM(r4*cl*hi)||'|'||SUM(r5)||','||SUM(r5*hi)||','||SUM(r5*ver)||','||SUM(r5*chl)||','||SUM(r5*chns)||','||SUM(r5*cl)||','||SUM(r5*(1-r0))||','||SUM(r0*(1-r5))||','||SUM(r5*cl*hi)||'|'||SUM(r6)||','||SUM(r6*hi)||','||SUM(r6*ver)||','||SUM(r6*chl)||','||SUM(r6*chns)||','||SUM(r6*cl)||','||SUM(r6*(1-r0))||','||SUM(r0*(1-r6))||','||SUM(r6*cl*hi)||'|'||SUM(r7)||','||SUM(r7*hi)||','||SUM(r7*ver)||','||SUM(r7*chl)||','||SUM(r7*chns)||','||SUM(r7*cl)||','||SUM(r7*(1-r0))||','||SUM(r0*(1-r7))||','||SUM(r7*cl*hi)||'|'||SUM(r8)||','||SUM(r8*hi)||','||SUM(r8*ver)||','||SUM(r8*chl)||','||SUM(r8*chns)||','||SUM(r8*cl)||','||SUM(r8*(1-r1))||','||SUM(r1*(1-r8))||','||SUM(r8*cl*hi)||'|'||SUM(r9)||','||SUM(r9*hi)||','||SUM(r9*ver)||','||SUM(r9*chl)||','||SUM(r9*chns)||','||SUM(r9*cl)||','||SUM(r9*(1-r1))||','||SUM(r1*(1-r9))||','||SUM(r9*cl*hi)||'|'||SUM(r10)||','||SUM(r10*hi)||','||SUM(r10*ver)||','||SUM(r10*chl)||','||SUM(r10*chns)||','||SUM(r10*cl)||','||SUM(r10*(1-r2))||','||SUM(r2*(1-r10))||','||SUM(r10*cl*hi)||'|'||SUM(r11)||','||SUM(r11*hi)||','||SUM(r11*ver)||','||SUM(r11*chl)||','||SUM(r11*chns)||','||SUM(r11*cl)||','||SUM(r11*(1-r2))||','||SUM(r2*(1-r11))||','||SUM(r11*cl*hi) r FROM s4 GROUP BY d, grp HAVING SUM(r2+r3+r4+r5+r6+r7+r8+r9)>0
